-- Booking email templates, redesigned (single source, editable HTML in the DB).
-- Shape: { customer|business: { <kind>: { <locale>: { subject, html } } } }.
-- Changes vs the previous seed (20260825130000):
--   * Optional details (staff, price) are wrapped in {{#staff}}…{{/staff}} /
--     {{#price}}…{{/price}} sections so the label+value row disappears entirely
--     when the booking has no staff member or no price (the edge function's
--     renderTemplate now resolves these conditional sections).
--   * Footer carries localized Terms · Privacy links (nandzz.com/terms|privacy)
--     alongside the "Powered by Nandzz" mark.
--   * A brand-coloured accent bar ({{brand_primary}}) at the top of the card.
-- Injected {{variables}} are unchanged: {{business}}, {{business_avatar}},
-- {{brand_primary}}/{{brand_accent}}/{{brand_background}} (the business's own
-- brand colours from profiles.brand_colors, falling back to Nandzz purple),
-- {{customer_name}}, {{customer_first_name}}, {{service}}, {{staff}},
-- {{date_time}}, {{price}}, {{manage_url}}. Edit via the nandzz-admin Email
-- templates page.
insert into public.app_settings (key, value, description)
values (
  'booking_email_template',
  $tpl${"customer":{"confirmation":{"en":{"subject":"Booking confirmed — {{service}}","html":"<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"color-scheme\" content=\"light only\" />\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f4f4f5\">\n  <tr><td align=\"center\" style=\"padding:28px 12px\">\n    <table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;width:560px;max-width:100%;background:#ffffff;border:1px solid #e9eaec;border-radius:16px;overflow:hidden\">\n      <!-- Brand accent bar -->\n      <tr><td style=\"height:4px;background:{{brand_primary}};font-size:0;line-height:0\">&nbsp;</td></tr>\n      <!-- Header -->\n      <tr><td style=\"padding:24px 28px 6px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n          <tr>\n            <td valign=\"middle\" style=\"padding-right:12px\">{{business_avatar}}</td>\n            <td valign=\"middle\" style=\"font:700 17px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{business}}</td>\n          </tr>\n        </table>\n      </td></tr>\n      <!-- Body -->\n      <tr><td style=\"padding:10px 28px 4px\">\n        <div style=\"font:700 22px/1.3 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827;margin:6px 0 10px\">You&#39;re booked!</div>\n        <div style=\"font:400 15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#4b5563\">Hi {{customer_first_name}}, your booking with {{business}} is confirmed. We look forward to seeing you.</div>\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f9fafb;border:1px solid #eef0f2;border-radius:12px;margin:16px 0 4px\">\n          <tr><td style=\"padding:4px 20px 16px\">\n            <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n      <tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Service</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{service}}</td></tr>\n      <tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Date &amp; time</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{date_time}}</td></tr>\n      {{#staff}}<tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">With</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{staff}}</td></tr>{{/staff}}\n      {{#price}}<tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Price</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{price}}</td></tr>{{/price}}\n            </table>\n          </td></tr>\n        </table>\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;margin:22px 0 2px\">\n          <tr><td align=\"center\" style=\"border-radius:9px;background:{{brand_primary}}\">\n            <a href=\"{{manage_url}}\" target=\"_blank\" style=\"display:inline-block;padding:13px 26px;font:600 15px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;text-decoration:none;border-radius:9px\">Manage booking</a>\n          </td></tr>\n        </table>\n      </td></tr>\n      <!-- Footer -->\n      <tr><td style=\"padding:22px 28px 26px\">\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;border-top:1px solid #eef0f2\">\n          <tr>\n            <td style=\"padding-top:16px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">\n              <a href=\"https://nandzz.com/terms\" target=\"_blank\" style=\"color:#6b7280;text-decoration:none\">Terms</a>\n              <span style=\"color:#d1d5db\">&nbsp;·&nbsp;</span>\n              <a href=\"https://nandzz.com/privacy\" target=\"_blank\" style=\"color:#6b7280;text-decoration:none\">Privacy</a>\n            </td>\n            <td align=\"right\" valign=\"middle\" style=\"padding-top:16px\">\n              <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\"><tr>\n                <td valign=\"middle\" style=\"padding-right:6px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">Powered by</td>\n                <td valign=\"middle\"><img src=\"https://nandzz.com/logo.png\" width=\"18\" height=\"19\" alt=\"Nandzz\" style=\"display:block;border:0\" /></td>\n              </tr></table>\n            </td>\n          </tr>\n        </table>\n      </td></tr>\n    </table>\n  </td></tr>\n</table>\n</body></html>"},"pt":{"subject":"Reserva confirmada — {{service}}","html":"<!DOCTYPE html>\n<html lang=\"pt\"><head><meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"color-scheme\" content=\"light only\" />\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f4f4f5\">\n  <tr><td align=\"center\" style=\"padding:28px 12px\">\n    <table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;width:560px;max-width:100%;background:#ffffff;border:1px solid #e9eaec;border-radius:16px;overflow:hidden\">\n      <!-- Brand accent bar -->\n      <tr><td style=\"height:4px;background:{{brand_primary}};font-size:0;line-height:0\">&nbsp;</td></tr>\n      <!-- Header -->\n      <tr><td style=\"padding:24px 28px 6px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n          <tr>\n            <td valign=\"middle\" style=\"padding-right:12px\">{{business_avatar}}</td>\n            <td valign=\"middle\" style=\"font:700 17px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{business}}</td>\n          </tr>\n        </table>\n      </td></tr>\n      <!-- Body -->\n      <tr><td style=\"padding:10px 28px 4px\">\n        <div style=\"font:700 22px/1.3 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827;margin:6px 0 10px\">Reserva confirmada!</div>\n        <div style=\"font:400 15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#4b5563\">Olá {{customer_first_name}}, sua reserva com {{business}} está confirmada. Esperamos por você.</div>\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f9fafb;border:1px solid #eef0f2;border-radius:12px;margin:16px 0 4px\">\n          <tr><td style=\"padding:4px 20px 16px\">\n            <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n      <tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Serviço</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{service}}</td></tr>\n      <tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Data e hora</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{date_time}}</td></tr>\n      {{#staff}}<tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Com</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{staff}}</td></tr>{{/staff}}\n      {{#price}}<tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Preço</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{price}}</td></tr>{{/price}}\n            </table>\n          </td></tr>\n        </table>\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;margin:22px 0 2px\">\n          <tr><td align=\"center\" style=\"border-radius:9px;background:{{brand_primary}}\">\n            <a href=\"{{manage_url}}\" target=\"_blank\" style=\"display:inline-block;padding:13px 26px;font:600 15px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;text-decoration:none;border-radius:9px\">Gerenciar reserva</a>\n          </td></tr>\n        </table>\n      </td></tr>\n      <!-- Footer -->\n      <tr><td style=\"padding:22px 28px 26px\">\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;border-top:1px solid #eef0f2\">\n          <tr>\n            <td style=\"padding-top:16px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">\n              <a href=\"https://nandzz.com/terms\" target=\"_blank\" style=\"color:#6b7280;text-decoration:none\">Termos</a>\n              <span style=\"color:#d1d5db\">&nbsp;·&nbsp;</span>\n              <a href=\"https://nandzz.com/privacy\" target=\"_blank\" style=\"color:#6b7280;text-decoration:none\">Privacidade</a>\n            </td>\n            <td align=\"right\" valign=\"middle\" style=\"padding-top:16px\">\n              <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\"><tr>\n                <td valign=\"middle\" style=\"padding-right:6px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">Desenvolvido por</td>\n                <td valign=\"middle\"><img src=\"https://nandzz.com/logo.png\" width=\"18\" height=\"19\" alt=\"Nandzz\" style=\"display:block;border:0\" /></td>\n              </tr></table>\n            </td>\n          </tr>\n        </table>\n      </td></tr>\n    </table>\n  </td></tr>\n</table>\n</body></html>"},"fr":{"subject":"Réservation confirmée — {{service}}","html":"<!DOCTYPE html>\n<html lang=\"fr\"><head><meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"color-scheme\" content=\"light only\" />\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f4f4f5\">\n  <tr><td align=\"center\" style=\"padding:28px 12px\">\n    <table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;width:560px;max-width:100%;background:#ffffff;border:1px solid #e9eaec;border-radius:16px;overflow:hidden\">\n      <!-- Brand accent bar -->\n      <tr><td style=\"height:4px;background:{{brand_primary}};font-size:0;line-height:0\">&nbsp;</td></tr>\n      <!-- Header -->\n      <tr><td style=\"padding:24px 28px 6px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n          <tr>\n            <td valign=\"middle\" style=\"padding-right:12px\">{{business_avatar}}</td>\n            <td valign=\"middle\" style=\"font:700 17px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{business}}</td>\n          </tr>\n        </table>\n      </td></tr>\n      <!-- Body -->\n      <tr><td style=\"padding:10px 28px 4px\">\n        <div style=\"font:700 22px/1.3 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827;margin:6px 0 10px\">C&#39;est réservé !</div>\n        <div style=\"font:400 15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#4b5563\">Bonjour {{customer_first_name}}, votre réservation avec {{business}} est confirmée. Au plaisir de vous voir.</div>\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f9fafb;border:1px solid #eef0f2;border-radius:12px;margin:16px 0 4px\">\n          <tr><td style=\"padding:4px 20px 16px\">\n            <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n      <tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Service</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{service}}</td></tr>\n      <tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Date et heure</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{date_time}}</td></tr>\n      {{#staff}}<tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Avec</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{staff}}</td></tr>{{/staff}}\n      {{#price}}<tr><td style=\"padding:14px 0 2px;font:600 11px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em\">Prix</td></tr>\n      <tr><td style=\"padding:0 0 2px;font:600 15px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{price}}</td></tr>{{/price}}\n            </table>\n          </td></tr>\n        </table>\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;margin:22px 0 2px\">\n          <tr><td align=\"center\" style=\"border-radius:9px;background:{{brand_primary}}\">\n            <a href=\"{{manage_url}}\" target=\"_blank\" style=\"display:inline-block;padding:13px 26px;font:600 15px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;text-decoration:none;border-radius:9px\">Gérer la réservation</a>\n          </td></tr>\n        </table>\n      </td></tr>\n      <!-- Footer -->\n      <tr><td style=\"padding:22px 28px 26px\">\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;border-top:1px solid #eef0f2\">\n          <tr>\n            <td style=\"padding-top:16px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">\n              <a href=\"https://nandzz.com/terms\" target=\"_blank\" style=\"color:#6b7280;text-decoration:none\">Conditions</a>\n              <span style=\"color:#d1d5db\">&nbsp;·&nbsp;</span>\n              <a href=\"https://nandzz.com/privacy\" target=\"_blank\" style=\"color:#6b7280;text-decoration:none\">Confidentialité</a>\n            </td>\n            <td align=\"right\" valign=\"middle\" style=\"padding-top:16px\">\n              <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\"><tr>\n                <td valign=\"middle\" style=\"padding-right:6px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">Propulsé par</td>\n                <td valign=\"middle\"><img src=\"https://nandzz.com/logo.png\" width=\"18\" height=\"19\" alt=\"Nandzz\" style=\"display:block;border:0\" /></td>\n              </tr></table>\n            </td>\n          </tr>\n        </table>\n      </td></tr>\n    </table>\n  </td></tr>\n</table>\n</body></html>"},"es":{"subject":"Reserva confirmada — {{service}}","html":"<!DOCTYPE html>\n<html lang=\"es\"><head><meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"color-scheme\" content=\"light only\" />\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f4f4f5\">\n  <tr><td align=\"center\" style=\"padding:28px 12px\">\n    <table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;width:560px;max-width:100%;background:#ffffff;border:1px solid #e9eaec;border-radius:16px;overflow:hidden\">\n      <!-- Brand accent bar -->\n      <tr><td style=\"height:4px;background:{{brand_primary}};font-size:0;line-height:0\">&nbsp;</td></tr>\n      <!-- Header -->\n      <tr><td style=\"padding:24px 28px 6px\">\n        <table role=\"presentation\" cellpadding=\"0\"