I,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{price}}</td></tr>{{/price}}\n            </table>\n          </td></tr>\n        </table>\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;margin:22px 0 2px\">\n          <tr><td align=\"center\" style=\"border-radius:9px;background:{{brand_primary}}\">\n            <a href=\"{{manage_url}}\" target=\"_blank\" style=\"display:inline-block;padding:13px 26px;font:600 15px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;text-decoration:none;border-radius:9px\">Gestisci prenotazione</a>\n          </td></tr>\n        </table>\n      </td></tr>\n      <!-- Footer -->\n      <tr><td style=\"padding:22px 28px 26px\">\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;border-top:1px solid #eef0f2\">\n          <tr>\n            <td style=\"padding-top:16px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">\n              <a href=\"https://nandzz.com/terms\" target=\"_blank\" style=\"color:#6b7280;text-decoration:none\">Termini</a>\n              <span style=\"color:#d1d5db\">&nbsp;·&nbsp;</span>\n              <a href=\"https://nandzz.com/privacy\" target=\"_blank\" style=\"color:#6b7280;text-decoration:none\">Privacy</a>\n            </td>\n            <td align=\"right\" valign=\"middle\" style=\"padding-top:16px\">\n              <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\"><tr>\n                <td valign=\"middle\" style=\"padding-right:6px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">Con tecnologia</td>\n                <td valign=\"middle\"><img src=\"https://nandzz.com/logo.png\" width=\"18\" height=\"19\" alt=\"Nandzz\" style=\"display:block;border:0\" /></td>\n              </tr></table>\n            </td>\n          </tr>\n        </table>\n      </td></tr>\n    </table>\n  </td></tr>\n</table>\n</body></html>"}}}}$tpl$::jsonb,
  'Booking email HTML templates (subject + html per type/locale, with {{variables}} and {{#section}} conditionals). Authoritative source read by the booking-notifications edge function; edit via the nandzz-admin Email templates page.'
)
